function admin_redirect(string $module): never { redirect('admin.php?module=' . rawurlencode($module)); }
function admin_product_slug(PDO $db, string $name, int $exceptId = 0): string { $base=artist_slug($name) ?: 'producto';$slug=$base;$n=2;do{$sql='SELECT id_producto FROM producto WHERE slug=:slug'.($exceptId?' AND id_producto<>:id':'').' LIMIT 1';$s=$db->prepare($sql);$params=['slug'=>$slug];if($exceptId)$params['id']=$exceptId;$s->execute($params);if(!$s->fetch())return $slug;$suffix='-'.$n++;$slug=substr($base,0,180-strlen($suffix)).$suffix;}while(true); }
function admin_record(PDO $db, string $module, int $id): ?array {
    $map=['productos'=>['producto','id_producto'],'categorias'=>['categoria_producto','id_categoria'],'artistas'=>['artista','id_artista'],'albumes'=>['album','id_album'],'pedidos'=>['pedido','id_pedido'],'usuarios'=>['usuario','id_usr'],'roles'=>['rol','id_rol']];
    [$table,$key]=$map[$module]; $s=$db->prepare("SELECT * FROM $table WHERE $key=:id"); $s->execute(['id'=>$id]); return $s->fetch() ?: null;
}
