            if ($albumId) { $s=$db->prepare('SELECT id_album FROM album WHERE id_album=:id');$s->execute(['id'=>$albumId]);if(!$s->fetch())throw new RuntimeException('El álbum seleccionado no existe.');$s=$db->prepare('SELECT nombre FROM categoria_producto WHERE id_categoria=:id');$s->execute(['id'=>$category]);if((string)$s->fetchColumn()!=='Álbumes musicales')throw new RuntimeException('Solo los productos de la categoría Álbumes musicales pueden vincularse a un álbum.'); }
