            $name=trim((string)($_POST['nombre']??''));$desc=trim((string)($_POST['descripcion']??'')); if(admin_length($name)<2||admin_length($name)>100||admin_length($desc)>255) throw new RuntimeException('Verifica el nombre y la descripción.');
