            $name=trim((string)($_POST['nombre']??''));$bio=trim((string)($_POST['biografia']??''));$genre=trim((string)($_POST['genero']??'')); if(admin_length($name)<2||admin_length($name)>150||admin_length($genre)>100) throw new RuntimeException('Verifica nombre y género.');
