        }
        if ($module==='pedidos' && $action==='state') { $state=in_array($_POST['estado']??'', ['pendiente','pagado','preparando','enviado','entregado','cancelado'],true)?$_POST['estado']:'';if(!$target||$state==='')throw new RuntimeException('Estado inválido.');$db->prepare('UPDATE pedido SET estado=:s WHERE id_pedido=:id')->execute(['s'=>$state,'id'=>$target]);flash('Estado del pedido actualizado.');admin_redirect($module); }
