if($module==='usuarios'){$where=[];if($query!==''){$where[]='(u.nom_usr LIKE :q OR u.mail LIKE :q_mail OR CAST(u.id_usr AS CHAR) LIKE :q_id)';$params['q']='%'.$query.'%';$params['q_mail']='%'.$query.'%';$params['q_id']='%'.$query.'%';}if($filter!==''){$where[]='u.tip_usu=:role';$params['role']=(int)$filter;}$sql='SELECT u.*,r.nombre rol FROM usuario u JOIN rol r ON r.id_rol=u.tip_usu'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY u.nom_usr';}
